mapper.select:
SELECT FROM s_venue_customer vc JOIN s_user_account u ON u.id=vc.user_id LEFT JOIN booking_stats bs ON bs.venueId=vc.venue_id AND bs.customerId=vc.id LEFT JOIN latest_valid_bookings vb ON vb.venueId=vc.venue_id AND vb.customerId=vc.id LEFT JOIN usual_hours uh ON uh.venueId=vc.venue_id AND uh.customerId=vc.id LEFT JOIN tag_names tn ON tn.venueId=vc.venue_id AND tn.customerId=vc.id WHERE vc.venue_id=#{venueId}
AND bs.lastCompletedAt IS NOT NULL AND bs.lastCompletedAt <= UTC_TIMESTAMP(3) - INTERVAL 30 DAY AND COALESCE(bs.futureConfirmedCount,0)=0
ORDER BY bs.lastCompletedAt IS NULL,bs.lastCompletedAt ASC,vc.id ASC

SELECT id,venue_id AS venueId,name,created_by_admin_id AS createdByAdminId,
       created_by_employee_id AS createdByEmployeeId,created_by_name AS createdByName,created_at AS createdAt
FROM s_venue_customer_tag WHERE venue_id=#{venueId} AND id=#{tagId}
